function SMA(data, period) {
  if (!data || data.length < period) return null;
  const slice = data.slice(data.length - period);
  const sum = slice.reduce((a, b) => a + b, 0);
  return sum / period;
}

function RSI(data, period = 14) {
  if (!data || data.length <= period) return null;
  let gains = 0, losses = 0;
  for (let i = data.length - period; i < data.length; i++) {
    const diff = data[i] - data[i - 1];
    if (diff >= 0) gains += diff;
    else losses -= diff;
  }
  const avgGain = gains / period;
  const avgLoss = losses / period;
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

const output = [];

for (const item of $input.all()) {
  const resultData = item.json.chart?.result?.[0];
  if (!resultData) continue;

  const symbol = resultData.meta?.symbol || 'UNKNOWN';
  const rawCloses = resultData.indicators?.quote?.[0]?.close || [];
  const closes = rawCloses.filter(v => v !== null && v !== undefined);

  if (closes.length === 0) continue;

  const lastClose = closes[closes.length - 1];
  const ma50Val = SMA(closes, 50);
  const ma200Val = SMA(closes, 200);
  const rsiVal = RSI(closes, 14);

  let signal = '⚪ Tidak ada sinyal saat ini';
  if (rsiVal !== null && rsiVal < 30) signal = '🔵 RSI Oversold (Potensi Buy)';
  else if (rsiVal !== null && rsiVal > 70) signal = '🔴 RSI Overbought (Potensi Sell)';
  else if (ma50Val !== null && ma200Val !== null && ma50Val > ma200Val) signal = '🟢 Golden Cross (Buy Signal)';
  else if (ma50Val !== null && ma200Val !== null && ma50Val < ma200Val) signal = '🔻 Death Cross (Sell Signal)';

  output.push({
    json: {
      symbol,
      lastClose: lastClose ? Number(lastClose.toFixed(2)) : null,
      rsi: rsiVal !== null ? Number(rsiVal.toFixed(2)) : 'N/A',
      ma50: ma50Val !== null ? Number(ma50Val.toFixed(2)) : 'N/A',
      ma200: ma200Val !== null ? Number(ma200Val.toFixed(2)) : 'N/A',
      signal
    }
  });
}

return output;

